"""Summarise existing validation evidence after all independent gates pass."""
import json
from pathlib import Path
import experiment_analysis as a

def main():
    saved=json.loads((a.AN/'experiment_workbook_verification.json').read_text(encoding='utf-8'))
    assert saved['status']=='Phase 8 complete', 'Saved workbook completion gates remain outstanding'
    result=json.loads((a.AN/'experiment_results.json').read_text(encoding='utf-8'));assert a.hashes()==result['input_hashes']
    doc=a.AN/'experiment_validation.md';text=doc.read_text(encoding='utf-8')
    details=[s.removeprefix('- PASS: ') for s in text.splitlines() if s.startswith('- PASS: ')]
    if details:(a.PRE/'python_check_details.json').write_text(json.dumps(details,indent=2),encoding='utf-8')
    extras=json.loads((a.PRE/'additional_validation.json').read_text(encoding='utf-8'));assert extras['passed']
    rows='\n'.join(f'| {k} | {v:,} |' for k,v in result['rows'].items())
    lines=['# Phase 8 validation — complete','',a.D1,'',a.D2,'','All experiment, saved workbook, refresh, preservation, reproducibility and visual gates pass. Native Excel was not automated: Artifact Tool recalculated the actual saved formula graph and the workbook is set to automatic Excel recalculation.','',f'Python generation checks: {result["checks_passed"]:,}, including per-cohort survivor checks. Full assertion names are retained in the audit directory, not counted as independent experiments. Additional boundary/null/matching fixtures pass.','', '| Interface | Rows |','|---|---:|',rows,'','- Exactly seven disjoint pairs; five first and two repeat pairs; seven treatments and seven controls. Sixteen eligible candidates; NF023 and NF057 remain reserves.','- All historical matching windows complete; no post-intervention matching input. Separate fixed streams and deterministic assignment.','- Integer member bridges, tier transfers, eligible exits, cohort identity, promotional protection and one-time billed increments reconcile. Zero caps and zero seasonal-driver fallbacks were needed in the fixed run.','- Ledger subscription revenue and revenue components reconcile within £0.01. Rate numerators and member exposure remain visible.','- Ten thousand whole-pair resamples; exact 32/128 assignment enumeration; zero-effect fixtures; unavailable small-group intervals; all governance boundaries and precedence verified.','- Power interface keys are unique; actual five-pair null rejection rate 3.10% is below the pre-specified 5% alpha under the historical planning proxy.','- All seven CSVs reproduce byte-identically. All source, generation, Phase 3–7 evidence and retained Phase 6 shared draws retain their original hashes.','',f'Saved workbook: 31 populated sheets, 27 earlier sheets and native resources preserved apart from authorised guidance updates. {saved["independent_cells_compared"]:,} saved values compare with independent Python results; maximum absolute difference {saved["max_difference"]:.3g}. {saved["formula_count"]:,} formula cells have evaluated caches. Formula errors: zero.','', 'Actual saved-formula recalculation passes, including live guardrail edits, missing-versus-zero policy values, outcome/seed stale detection, hidden unavailable intervals and scenario selector independence/restoration. A full comparison refresh succeeds with CURRENT captures. Phase 6/7 replacement plumbing preserves all experiment sheets and current guidance on a disposable copy using their already validated segments.','', 'Every new sheet, native chart, three commercial figures and affected guidance area received visual review. Source-linked monthly/period comparisons and monitoring arithmetic are separated from independent terminal checks.','', 'Evidence files: experiment_results.json, experiment_workbook_verification.json, and the Phase 8 audit directory’s reproduction.json, saved_recalculation.json, refresh_verification.json, refresh_compatibility.json, additional_validation.json and visual_review.json.','', 'Remaining simplifications: small samples, proxy trading residuals, monthly billing exposure approximations, frozen competitor recurring prices and no upgrades/freezes/bad-debt or future operational shocks. Simulated estimates are not independent validation, actual realised revenue or profit.','', 'Phase 8 complete; Phase 9 next.']
    doc.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    report=a.AN/'experiment_report.md';s=report.read_text(encoding='utf-8')
    s=s.replace('Workbook completion is recorded separately after saved-file recalculation, parity, refresh and visual review.','The 31-sheet workbook passes saved-file recalculation, Python parity, refresh/stale tests, preservation and visual review; see experiment_workbook_verification.json. Phase 8 is complete.')
    s=s.replace('Phase 9 will design the Power BI communication layer after Phase 8 validation is complete.','Phase 8 is complete. Phase 9 is next: the Power BI communication layer.')
    report.write_text(s,encoding='utf-8');print('Phase 8 audit and report marked complete from independently passed evidence.')

if __name__=='__main__':main()
